import{_ as n,a0 as p,w as o,s as r,I as e,x as i,a1 as a,A as l,ao as d}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const C=JSON.parse('{"title":"創建局域網內的離線 Yum 倉庫 | LCTT x X-CMD","titleTemplate":false,"description":"創建局域網內的離線 Yum 倉庫 | LCTT (201802) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"創建局域網內的離線 Yum 倉庫 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"創建局域網內的離線 Yum 倉庫 | LCTT (201802) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201802/20180103 Creating an Offline YUM repository for LAN","title":"創建局域網內的離線 Yum 倉庫","tag":"201802","desc":""},"relativePath":"201802/20180103 Creating an Offline YUM repository for LAN.md","filePath":"[post].md"}'),u={name:"201802/20180103 Creating an Offline YUM repository for LAN.md"};function h(g,s,f,b,k,m){const t=p("Link");return o(),r("div",null,[s[22]||(s[22]=e("h1",{id:"創建局域網內的離線-yum-倉庫",tabindex:"-1"},[i("創建局域網內的離線 Yum 倉庫 "),e("a",{class:"header-anchor",href:"#創建局域網內的離線-yum-倉庫","aria-label":"Permalink to “創建局域網內的離線 Yum 倉庫”"},"​")],-1)),e("p",null,[s[1]||(s[1]=i("在早先的教程中，我們討論了",-1)),a(t,{href:"https://linux.cn/article-9296-1.html"},{default:l(()=>[...s[0]||(s[0]=[i("如何使用 ISO 鏡像和在線 Yum 倉庫的方式來創建自己的 Yum 倉庫 ",-1)])]),_:1}),s[2]||(s[2]=i("。創建自己的 Yum 倉庫是一個不錯的想法，但若網絡中只有 2-3 台 Linux 機器那就沒啥必要了。不過若你的網絡中有大量的 Linux 服務器，而且這些服務器還需要定時進行升級，或者你有大量服務器無法直接訪問互聯網，那麼創建自己的 Yum 倉庫就很有必要了。",-1))]),s[23]||(s[23]=e("p",null,"當我們有大量的 Linux 服務器，而每個服務器都直接從互聯網上升級系統時，數據消耗會很可觀。為了節省數據量，我們可以創建個離線 Yum 源並將之分享到本地網絡中。網絡中的其他 Linux 機器就可以直接從本地 Yum 上獲取系統更新，從而節省數據量，而且傳輸速度也會很好。",-1)),s[24]||(s[24]=e("p",null,"我們可以使用下面兩種方法來分享 Yum 倉庫：",-1)),s[25]||(s[25]=e("ul",null,[e("li",null,"使用 Web 服務器（Apache）"),e("li",null,"使用 FTP 服務器（VSFTPD）")],-1)),e("p",null,[s[4]||(s[4]=i("在開始講解這兩個方法之前，我們需要先根據",-1)),a(t,{href:"https://linux.cn/article-9296-1.html"},{default:l(()=>[...s[3]||(s[3]=[i("之前的教程",-1)])]),_:1}),s[5]||(s[5]=i("創建一個 Yum 倉庫。",-1))]),s[26]||(s[26]=d(`<h3 id="使用-web-服務器" tabindex="-1">使用 Web 服務器 <a class="header-anchor" href="#使用-web-服務器" aria-label="Permalink to “使用 Web 服務器”">​</a></h3><p>首先在 Yum 服務器上安裝 Web 服務器（Apache），我們假設服務器 IP 是 <code>192.168.1.100</code>。我們已經在這台系統上配置好了 Yum 倉庫，現在我們來使用 <code>yum</code> 命令安裝 Apache Web 服務器，</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ yum install httpd</span></span></code></pre></div><p>下一步，拷貝所有的 rpm 包到默認的 Apache 根目錄下，即 <code>/var/www/html</code>，由於我們已經將包都拷貝到了 <code>/YUM</code> 下，我們也可以創建一個軟連接來從 <code>/var/www/html</code> 指向 <code>/YUM</code>。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ ln -s /var/www/html/Centos /YUM</span></span></code></pre></div><p>重啓 Web 服務器應用改變：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ systemctl restart httpd</span></span></code></pre></div><h4 id="配置客户端機器" tabindex="-1">配置客户端機器 <a class="header-anchor" href="#配置客户端機器" aria-label="Permalink to “配置客户端機器”">​</a></h4><p>服務端的配置就完成了，現在需要配置下客户端來從我們創建的離線 Yum 中獲取升級包，這裏假設客户端 IP 為 <code>192.168.1.101</code>。</p><p>在 <code>/etc/yum.repos.d</code> 目錄中創建 <code>offline-yum.repo</code> 文件，輸入如下信息，</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ vi /etc/yum.repos.d/offline-yum.repo</span></span></code></pre></div><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>name=Local YUM</span></span>
<span class="line"><span>baseurl=http://192.168.1.100/CentOS/7</span></span>
<span class="line"><span>gpgcheck=0</span></span>
<span class="line"><span>enabled=1</span></span></code></pre></div><p>客户端也配置完了。試一下用 <code>yum</code> 來安裝/升級軟件包來確認倉庫是正常工作的。</p><h3 id="使用-ftp-服務器" tabindex="-1">使用 FTP 服務器 <a class="header-anchor" href="#使用-ftp-服務器" aria-label="Permalink to “使用 FTP 服務器”">​</a></h3><p>在 FTP 上分享 Yum，首先需要安裝所需要的軟件包，即 vsftpd。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ yum install vsftpd</span></span></code></pre></div><p>vsftp 的默認根目錄為 <code>/var/ftp/pub</code>，因此你可以拷貝 rpm 包到這個目錄，或者為它創建一個軟連接：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ ln -s /var/ftp/pub /YUM</span></span></code></pre></div><p>重啓服務應用改變：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ systemctl restart vsftpd</span></span></code></pre></div><h4 id="配置客户端機器-1" tabindex="-1">配置客户端機器 <a class="header-anchor" href="#配置客户端機器-1" aria-label="Permalink to “配置客户端機器”">​</a></h4><p>像上面一樣，在 <code>/etc/yum.repos.d</code> 中創建 <code>offline-yum.repo</code> 文件，並輸入下面信息，</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ vi /etc/yum.repos.d/offline-yum.repo</span></span></code></pre></div><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>[Offline YUM]</span></span>
<span class="line"><span>name=Local YUM</span></span>
<span class="line"><span>baseurl=ftp://192.168.1.100/pub/CentOS/7</span></span>
<span class="line"><span>gpgcheck=0</span></span>
<span class="line"><span>enabled=1</span></span></code></pre></div>`,24)),e("p",null,[s[7]||(s[7]=i("現在客户機可以通過 ftp 接收升級了。要配置 vsftpd 服務器為其他 Linux 系統分享文件，請",-1)),a(t,{href:"http://linuxtechlab.com/ftp-secure-installation-configuration/"},{default:l(()=>[...s[6]||(s[6]=[i("閲讀這篇指南",-1)])]),_:1}),s[8]||(s[8]=i("。",-1))]),s[27]||(s[27]=e("p",null,"這兩種方法都很不錯，你可以任意選擇其中一種方法。有任何疑問或這想説的話，歡迎在下面留言框中留言。",-1)),s[28]||(s[28]=e("hr",null,null,-1)),e("p",null,[s[10]||(s[10]=i("via: ",-1)),a(t,{href:"http://linuxtechlab.com/offline-yum-repository-for-lan/"},{default:l(()=>[...s[9]||(s[9]=[i("http://linuxtechlab.com/offline-yum-repository-for-lan/",-1)])]),_:1})]),e("p",null,[s[14]||(s[14]=i("作者：",-1)),a(t,{href:"http://linuxtechlab.com/author/shsuain/"},{default:l(()=>[...s[11]||(s[11]=[i("Shusain",-1)])]),_:1}),s[15]||(s[15]=i(" 譯者：",-1)),a(t,{href:"https://github.com/lujun9972"},{default:l(()=>[...s[12]||(s[12]=[i("lujun9972",-1)])]),_:1}),s[16]||(s[16]=i(" 校對：",-1)),a(t,{href:"https://github.com/wxy"},{default:l(()=>[...s[13]||(s[13]=[i("wxy",-1)])]),_:1})]),e("p",null,[s[19]||(s[19]=i("本文由 ",-1)),a(t,{href:"https://github.com/LCTT/TranslateProject"},{default:l(()=>[...s[17]||(s[17]=[i("LCTT",-1)])]),_:1}),s[20]||(s[20]=i(" 原創編譯，",-1)),a(t,{href:"https://linux.cn/"},{default:l(()=>[...s[18]||(s[18]=[i("Linux中國",-1)])]),_:1}),s[21]||(s[21]=i(" 榮譽推出",-1))])])}const x=n(u,[["render",h]]);export{C as __pageData,x as default};
